  bounce 0.8
  minBounceSpeed 0
  collidables [
    USE F_C
    USE A_C
    USE B_C
  ]
}

DEF S CollisionSensor {
  collider USE CC
}

DEF TS TimeSensor {
  loop TRUE
}

DEF SC Script {
  inputOnly      SFTime  tick
  outputOnly     SFBool  en
  initializeOnly SFFloat s0 9.466848e8

  url "ecmascript:
var done = [ ];
function tick (v)
{
  if (s0 < 0) s0 = v;
  var f = Math .round ((v - s0) * 60);
  if (f >= 40 && !done[0]) { done[0] = true; en = false; }
  if (f >= 80 && !done[1]) { done[1] = true; en = true; }
}
"
}

ROUTE TS.time TO SC.tick
ROUTE SC.en TO S.set_enabled

